function progressHTML(){return `<div class="progress-panel" aria-live="polite"><progress ${progressInfo?.progress!=null?`value="${progressInfo.progress}"`:''} max="1" ${!busy?'hidden':''}></progress><p data-progress>${esc(progressInfo?.text||'')}</p>${busy?`<button class="action-link" data-action="cancel">${tr('Interrompi','Cancel')}</button>`:''}</div>`;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),5000);}
function progress(p){if(p.phase){const label=p.phase==='saved'?tr('File AI salvato','AI file saved'):p.phase==='cache'?tr('Caricamento dal dispositivo','Loading saved files'):p.phase==='download'?tr('Salvataggio del modello','Saving model'):tr('Avvio AI locale','Starting local AI');p={...p,text:label+(p.file?' · '+p.file:'')+(p.total?` · ${(p.loaded/1e6).toFixed(1)} / ${(p.total/1e6).toFixed(1)} MB`:p.progress!=null?' · '+Math.round(p.progress*100)+'%':'')};}progressInfo=p;for(const el of root.querySelectorAll('[data-progress]'))el.textContent=p.text;for(const el of root.querySelectorAll('progress')){el.hidden=false;if(p.progress==null)el.removeAttribute('value');else el.value=p.progress;}}
function friendly(error){
  if(error.message==='STORAGE_BUSY')return tr('Chiudi le altre schede Twin e riapri questa pagina per completare l’aggiornamento dei dati.','Close other Twin tabs and reopen this page to finish updating local storage.');
  if(error.message==='DEVICE_KEY_MISSING')return tr('La chiave locale non è disponibile. Ripristina il tuo backup con il codice di attivazione; non cancellare i dati del sito.','The local encryption key is unavailable. Restore your backup with its activation code; do not clear site data.');
  if(error.message==='AUDIO_STORAGE_FULL')return tr('Spazio registrazioni pieno (20 MiB). Esporta un backup e rimuovi alcune note vocali.','Recording storage is full (20 MiB). Export a backup and remove some voice notes.');
  if(error.name==='NotAllowedError')return tr('Accesso al microfono negato. Abilitalo per Twin nelle impostazioni di Safari o del browser.','Microphone access was denied. Enable it for Twin in Safari or browser settings.');
  if(error.message==='VOICE_NOT_SUPPORTED')return tr('Questo browser non supporta la registrazione. Usa Safari aggiornato o un browser compatibile.','This browser does not support recording. Use updated Safari or a compatible browser.');
  if(error.message==='VOICE_TOO_LARGE'||error.message==='VOICE_TOO_LONG')return tr('Ogni registrazione può durare al massimo 3 minuti e occupare 4 MiB.','Each recording can be at most 3 minutes and 4 MiB.');
  if(error.message==='VOICE_SILENT'||error.message==='VOICE_EMPTY')return tr('Non è stato rilevato audio utilizzabile. Registra di nuovo vicino al microfono.','No usable audio was detected. Record again near the microphone.');
  if(error.message?.startsWith('VOICE_'))return tr('Operazione vocale non riuscita. La registrazione già preparata viene conservata; puoi riascoltarla e riprovare.','Voice operation failed. Your prepared recording is kept; you can replay it and retry.');
  if(error.message==='MODEL_STORAGE_FULL')return tr('Spazio Safari insufficiente. Libera spazio sul dispositivo e riprendi; non cancellare i dati del sito Twin.','Safari storage is full. Free device storage and resume; do not clear Twin’s site data.');
  if(error.message==='MODEL_STORAGE_UNAVAILABLE')return tr('Safari non può salvare i modelli. Usa una scheda normale, non privata.','Safari cannot save models. Use a normal, non-private tab.');
  if(error.message==='MODEL_DOWNLOAD_BUSY')return tr('Un’altra scheda Twin sta scaricando questo modello. Chiudi le altre schede Twin e riprova.','Another Twin tab is downloading this model. Close the other Twin tabs and retry.');
  if(error.message?.startsWith('MODEL_DOWNLOAD'))return tr('Download interrotto. Le parti salvate restano sul dispositivo. Riprendi da Completa la preparazione oppure da Verifica app e file AI.','Download interrupted. Saved parts are kept. Resume with Finish setup or Check app & AI files.');
  if(error.message==='AI_MODELS_OFFLINE')return tr('I file AI non sono completi su questo dispositivo. Collegati al Wi-Fi e completa una volta la preparazione.','AI files are incomplete on this device. Connect to Wi-Fi and complete setup once.');
  if(error.message==='AI_WORKER_FAILED'||error.message==='AI_WORKER_MESSAGE_FAILED'||/wasm|WebAssembly|memory|allocation|backend|fetch|network|device lost/i.test(error.message||''))return tr('L’AI locale non è partita. Il diario resta salvato. Riprova con Wi-Fi e spazio libero; se disponibile, prova la modalità CPU.','Local AI could not start. Your diary is still saved. Retry with Wi-Fi and free storage; if available, try CPU mode.');
  if(error.message==='CONFLICT')return tr('Un’altra scheda ha modificato questi dati. Riapri Twin per caricare la versione aggiornata.','Another tab changed this vault. Reopen Twin to load the latest version.');
  if(error.message==='VAULT_FULL')return tr('Archivio pieno (24 MiB). Esporta un backup e riduci le voci prima di continuare.','Vault full (24 MiB). Export a backup and reduce entries before continuing.');
  if(error.message==='AI_CANCELLED')return tr('Operazione interrotta.','Operation cancelled.');
  if(error.message?.startsWith('LICENSE'))return tr('Codice non valido o verifica non supportata da questo browser.','Invalid code or verification unsupported in this browser.');
  if(error.name==='QuotaExceededError')return tr('Spazio esaurito. Esporta un backup e libera spazio sul dispositivo.','Storage full. Export a backup and free device storage.');
  if(error.name==='OperationError')return tr('Codice del backup o vecchia password errati, oppure dati cifrati danneggiati.','The backup code or old password is incorrect, or encrypted data is damaged.');
  return tr('Operazione non riuscita. Controlla connessione, spazio e compatibilità del browser. Riprova o usa CPU.','Operation failed. Check connection, storage and browser compatibility. Retry or use CPU.');
}
async function run(fn){
  if(busy)return;busy=true;errorMessage='';errorDetail='';const epoch=activeEpoch;
  let wakeLock;
  root.querySelectorAll('button:not([data-action="cancel"]):not([data-action="lock"]),input,textarea,select').forEach(el=>el.disabled=true);
  root.querySelectorAll('.progress-panel').forEach(el=>{el.querySelector('progress').hidden=false;if(!el.querySelector('[data-action=cancel]')){const b=document.createElement('button');b.type='button';b.className='action-link';b.dataset.action='cancel';b.textContent=tr('Interrompi','Cancel');el.append(b);}});
  try{
    // Keep the screen awake for the entire AI operation, including generation.
    try{wakeLock=await navigator.wakeLock?.request('screen');}catch{}
    if(epoch===activeEpoch)await fn(epoch);
  }catch(error){if(epoch===activeEpoch){errorMessage=friendly(error);errorDetail=String(error.message||error).slice(0,1200);toast(errorMessage);}}
  // Release the wake lock after the operation while leaving the journal open.
  finally{try{await wakeLock?.release();}catch{}if(epoch===activeEpoch){busy=false;progressInfo=null;render();}}
}
function checkEpoch(epoch){if(epoch!==activeEpoch||!unlocked)throw new Error('AI_CANCELLED');}
async function persist(candidate=vault,epoch=activeEpoch,options={}){
  validateVault(candidate);const encrypted=await sealDevice(candidate,key);checkEpoch(epoch);
  const next=await writeRecord(encrypted,revision,options);checkEpoch(epoch);
  revision=next;record={...encrypted,revision};vault=candidate;
}
